/** Independent sparse-sheet fixture oracle; historical rows are never retained by the consumer. */
export function fixtureDetailData(view: View, kind: DetailKind, id: string, cursor = ""): StateDetail {
  if (kind === "transaction") return fixtureTransactionDetail(view, id, cursor);
  const ss = "parts" in view ? view.parts : [view];
  const matches = (s: State) => kind === "mail" ? s.to_check.some((r) => r.key === id)
    : kind === "settlement" ? s.settlements?.some((r) => r.id === id)
    : kind === "order" ? s.emag_tasks?.some((r) => `${s.co}:${r.id}` === id)
    : kind === "issued" ? s.issued.some((r) => r.id === id || r.local_id === id)
    : (kind === "invoice" ? s.invoices : s.documents).some((r) => r.id === id);
  const source = ss.find(matches);
  if (!source) throw new Error("document not found");
  const s = structuredClone(source);
  const invoice = kind === "invoice" ? s.invoices.find((r) => r.id === id) : undefined;
  const issued = kind === "issued" ? s.issued.find((r) => r.id === id || r.local_id === id) : undefined;
  const doc = kind === "document" ? s.documents.find((r) => r.id === id) : undefined;
  const settlement = kind === "settlement" ? s.settlements?.find((r) => r.id === id) : undefined;
  const order = kind === "order" ? s.emag_tasks?.find((r) => `${s.co}:${r.id}` === id) : undefined;
  const row = purchases(s).find((p) => invoice ? p.invoice?.id === id : doc && p.doc?.id === id);
  const reversals = issued?.reversed_by?.flatMap((local) => s.issued.filter((r) => r.local_id === local)) ?? [];
  const all = invoice?.credits ?? settlement?.lines ?? reversals, start = Number(cursor || 0);
  const related = { data: all.slice(start, start + 50), total: all.length, next_cursor: start + 50 < all.length ? String(start + 50) : null };
  const invoices = [invoice ?? row?.invoice].filter((r): r is Invoice => !!r);
  if (invoice) invoice.credits = related.data as NonNullable<Invoice["credits"]>;
  const selectedIssued = issued ? [issued, ...s.issued.filter((r) => !!issued.storno_of && r.local_id === issued.storno_of), ...reversals.slice(start, start + 50)]
    : order?.draft_id ? s.issued.filter((r) => r.local_id === order.draft_id).slice(0, 1) : [];
  if (issued) issued.reversed_by = reversals.slice(start, start + 50).map((r) => r.local_id!);
  const documents = [doc ?? row?.doc].filter((r): r is NonNullable<typeof r> => !!r);
  const partnerIds = new Set([...invoices, ...(issued ? [issued] : []), ...documents].map((r) => r.partner));
  const state = { ...fixtureShell(s), invoices, issued: selectedIssued.map((r) => boundedRecord(r) as Issued), documents,
    settlements: settlement ? [{ ...settlement, lines: related.data as Settlement["lines"], links: { ...settlement.links, issued: settlement.links.issued.slice(0, 50) } }] : [],
    emag_tasks: order ? [order] : [],
    expenses: s.expenses.filter((e) => kind === "invoice" ? e.invoice === id : kind === "document" && e.document === id),
    partners: s.partners.filter((p) => partnerIds.has(p.id)).map((p) => ({ ...p, held: [] })),
    refused: s.refused.filter((r) => invoices.some((i) => i.id === r.id)),
    to_check: kind === "mail" ? s.to_check.filter((m) => m.key === id) : [],
  };
  const sheet = invoice ?? issued;
  const lines = sheet ? (fixtureLines as Record<string, InvoiceLines>)[`${kind}:${sheet.id}`] ?? { lines: [], currency: "", truncated: false, unavailable: true, totals: null } : undefined;
  return { state, related, ...(lines ? { lines } : {}) };
}

