/** Context-only shell used by the independent detail fixture selectors. */
function fixtureShell(s: State): State {
  const accountant = s.accountant.cui ? s.partners.find((p) => p.cui === s.accountant.cui) : undefined;
  return { ...s, ...Object.fromEntries(Object.entries(s).filter(([, v]) => Array.isArray(v)).map(([key]) => [key, []])),
    companies: s.companies, news: s.news, sales_origins: s.sales_origins, bank_connections: s.bank_connections,
    accountant: { ...s.accountant, partner: accountant ? { id: accountant.id, name: accountant.name, cui: accountant.cui } : null },
    rules: s.rules, recurrences: s.recurrences, firm_cards: s.firm_cards, files: s.files, payment_file_defaults: s.payment_file_defaults,
    transactions: { ...s.transactions, rows: [], remembered: [] }, dashboard: { ...s.dashboard, upcoming: [] },
    cod: s.cod ? { ...s.cod, rows: [], tasks: [] } : undefined };
}

function fixtureTransactionDetail(view: View, id: string, cursor: string): StateDetail {
  const s = ("parts" in view ? view.parts : [view]).find((p) => p.transactions.rows.some((t) => t.id === id))!;
  const tx = s.transactions.rows.find((t) => t.id === id)!, e = tx.explanation;
  const link = e && "link" in e ? e.link : undefined;
  const source = tx.direction === "credit" ? s.issued : s.invoices;
  const rows: CoveredRow[] = [
    ...(link?.parts ?? []).map((p) => { const invoice = source.find((r) => r.id === p.id);
      return { ...p, kind: "invoice" as const, number: invoice?.number ?? p.id, left: invoice?.left ?? "0.00", currency: invoice?.currency ?? tx.currency }; }),
    ...(link?.payments ?? []).map((payment, i) => ({ kind: "payment" as const, id: String(i), payment })),
  ];
  const start = Number(cursor || 0), ids = [link?.partner, tx.partner];
  const state = { ...fixtureShell(s), transactions: { ...s.transactions, remembered: [],
    rows: [boundedRecord(tx) as Transaction, ...s.transactions.rows.filter((t) => e?.kind === "transfer" && t.id === e.other).map((t) => boundedRecord(t) as Transaction)] },
    partners: s.partners.filter((p) => ids.includes(p.id)).map((p) => ({ ...p, held: [], report_formats: [] })),
    settlements: (s.settlements ?? []).filter((r) => e?.kind === "collection" && r.id === e.settlement).map((r) => boundedRecord(r) as Settlement) };
  return { state, related: { data: rows.slice(start, start + 50), total: rows.length, next_cursor: start + 50 < rows.length ? String(start + 50) : null },
    transaction: { said: said(tx, s), parts_count: link?.parts.length ?? 0, payments_count: link?.payments.length ?? 0,
      choices: tx.can_link ? fixtureTransactionChoicesData(s, { id }).pages : {} } };
}

/** The former form's complete selectors; only their requested option page reaches the app. */
function fixtureOffered(s: State, t: Transaction, partner: string): TransactionInvoiceChoice[] {
  const credit = t.direction === "credit", link = t.explanation && "link" in t.explanation ? t.explanation.link : undefined;
  const mine = new Map(link?.kind === "documents" ? link.parts.map((p) => [p.id, p.amount]) : []);
  const source = credit ? s.issued : s.invoices, curs = [t.currency, t.orig?.currency].filter(Boolean);
  const open = source.filter((r) => partner && (r.partner === partner || (credit && s.partners.find((p) => p.id === partner)?.held?.some((h) => h.invoice === r.id)))
    && (r.status === "open" || r.status === "marked") && (!credit || (!(r as Issued).rejected && (r as Issued).local_id !== r.id)))
    .filter((r) => cents(r.left) > 0n && curs.includes(credit ? r.currency ?? undefined : r.currency || "RON"))
    .sort((a, b) => (a.issue_date ?? "").localeCompare(b.issue_date ?? "") || textOrder(a.number, b.number));
  const pick = (r: typeof source[number], left: string) => ({ id: r.id, number: r.number, date: r.issue_date, left, total: r.total,
    currency: r.currency || "RON", partner: r.partner, selected: mine.has(r.id), position: 0 });
  return [...open.map((r) => pick(r, fromCents(cents(r.left) + cents(mine.get(r.id) ?? "0")))),
    ...[...mine].filter(([id]) => !open.some((r) => r.id === id)).flatMap(([id, amount]) => {
      const r = source.find((r) => r.id === id);
      return r && (r.partner === partner || (credit && link?.partner === partner)) ? [pick(r, amount)] : [];
    })].map((r, position) => ({ ...r, position }));
}

/** transaction_choices.proposed: the one open invoice the details name by number, at exactly what is left of it; else
 * the AI integration's invoices that add up to it. */
function fixtureProposed(s: State, t: Transaction): TransactionInvoiceChoice[] {
  const plain = (v: string) => (fold(v).match(/[0-9a-z]+/g) ?? []).join(" "), text = ` ${plain(t.details ?? "")} `;
  const named = (n: string) => { const p = plain(n);
    return p.length >= 3 && /[0-9]/.test(p) && (text.includes(` ${p} `) || text.includes(` ${p.replaceAll(" ", "")} `)); };
  const credit = t.direction === "credit", source = credit ? s.issued : s.invoices, curs = [t.currency, t.orig?.currency];
  const found = t.explanation || !t.details ? [] : source.filter((r) => (r.status === "open" || r.status === "marked") && cents(r.left) > 0n
    && curs.includes(credit ? r.currency ?? undefined : r.currency || "RON") && (!credit || (!(r as Issued).rejected && (r as Issued).local_id !== r.id))
    && named(r.number));
  const r = found.length === 1 ? found[0] : undefined, currency = r ? r.currency || "RON" : "";
  const paid = t.currency === currency ? t.amount : t.orig?.currency === currency ? t.orig.amount : null;
  const pick = (r: typeof source[number], position: number) => ({ id: r.id, number: r.number, date: r.issue_date, left: r.left,
    total: r.total, currency: r.currency || "RON", partner: r.partner, selected: false, position });
  if (r && paid && cents(paid) === cents(r.left)) return [pick(r, 0)];
  // else the AI integration's invoices, while all are open, in one currency, and what is left of them is the amount
  const ids = t.explanation || t.proposal?.kind !== "ai" ? [] : t.proposal.invoices;
  const rows = ids.flatMap((id) => source.filter((x) => x.id === id && (x.status === "open" || x.status === "marked") && cents(x.left) > 0n));
  const cur = new Set(rows.map((x) => x.currency || "RON")), one = cur.size === 1 ? [...cur][0] : "";
  const due = t.currency === one ? t.amount : t.orig?.currency === one ? t.orig.amount : null;
  const sum = rows.reduce((n, x) => n + cents(x.left), 0n);
  return ids.length && rows.length === ids.length && due && sum === cents(due.replace("-", "")) ? rows.map(pick) : [];
}

const textOrder = (a: string, b: string) => a.toLowerCase() < b.toLowerCase() ? -1 : a.toLowerCase() > b.toLowerCase() ? 1 : 0;
export function fixtureTransactionChoicesData(view: View, query: TransactionChoiceQuery, prepared?: Payment[]): TransactionChoices {
  const s = ("parts" in view ? view.parts : [view]).find((p) => p.transactions.rows.some((t) => t.id === query.id))!;
  const t = s.transactions.rows.find((t) => t.id === query.id)!, credit = t.direction === "credit";
  const link = t.explanation && "link" in t.explanation ? t.explanation.link : undefined;
  const proposed = fixtureProposed(s, t), partner = query.partner ?? (link?.partner || proposed[0]?.partner || t.partner || "");
  const offered = fixtureOffered(s, t, partner), selected = fixtureOffered(s, t, link?.partner ?? "").filter((r) => r.selected);
  const payments = prepared ?? fixturePreparedPayments(s.co);
  const lei = t.currency === "RON" ? t.amount : t.orig?.currency === "RON" ? t.orig.amount.replace("-", "") : null; // the debit's own lei amount
  const records: { [K in keyof TransactionChoiceRows]: TransactionChoiceRows[K][] } = {
    partners: s.partners.filter((p) => p.roles.includes(credit ? "client" : "supplier") || (credit && p.held?.length))
      .sort((a, b) => textOrder(a.name || `CUI ${a.cui}`, b.name || `CUI ${b.cui}`)).map((p) => ({ ...p, held: [], report_formats: [] })),
    invoices: offered, selected, proposed, payments: credit || !lei ? []
      : payments.map((payment, i) => ({ id: `fixture-payment-${s.co}-${i}`, payment })).filter((r) => query.q?.trim() || cents(r.payment.amount) === cents(lei)),
    receipts: credit ? [] : s.documents.filter((d) => d.held && d.amount === null && !d.sent && !d.invoice),
  };
  const names = query.collection ? [query.collection] : ["proposed", "partners", "invoices", "payments", "selected", "receipts"] as const;
  const q = fold((query.q ?? "").trim()), start = Number(query.cursor || 0), take = Number(query.limit ?? 50);
  return { pages: Object.fromEntries(names.map((name) => {
    const rows = records[name].filter((r) => !q || fold(name === "partners" ? `${(r as Partner).name || `CUI ${(r as Partner).cui}`} ${(r as Partner).cui || ""}`
      : name === "payments" ? ["payee", "ref", "details", "amount"].map((key) => (r as TransactionChoiceRows["payments"]).payment[key as keyof Payment] || "").join(" ")
        : ["number", "date", "left", "total"].map((key) => (r as TransactionInvoiceChoice)[key as keyof TransactionInvoiceChoice] || "").join(" ")).includes(q));
    return [name, { data: rows.slice(start, start + take).map((r) => boundedRecord(r)), total: rows.length, next_cursor: start + take < rows.length ? String(start + take) : null }];
  })) };
}

