/** PartnerBody's complete selectors, retained as an independent fixture oracle. */
export function fixturePartnerPagesData(view: View, query: PartnerQuery): PartnerPages {
  const ss = "parts" in view ? view.parts : [view];
  const s = query.id ? ss.find((s) => s.partners.some((p) => p.id === query.id)) : ss[0];
  if (!s) throw new Error("partner not found");
  const p = s.partners.find((p) => p.id === query.id);
  const issuedNumbers = new Map(s.issued.map((r) => [r.id, r.number]));
  const old = (direction: HistoryInvoice["direction"]) => s.history.filter((r) => r.direction === direction);
  const newest = <T extends { issue_date: string | null }>(rows: T[]) => rows.sort((a, b) => (b.issue_date ?? "").localeCompare(a.issue_date ?? ""));
  const records: { [K in keyof PartnerRows]: PartnerRows[K][] } = {
    invoices: newest([...s.invoices, ...old("received")].filter((r) => r.partner === p?.id)),
    issued: newest([...s.issued, ...old("issued")].filter((r) => r.partner === p?.id)),
    transactions: s.transactions.rows.filter((t) => t.explanation && "link" in t.explanation && t.explanation.link?.partner === p?.id)
      .map((t) => ({ id: t.id, company: s.co, transaction: t, said: said(t, s) })),
    held: (p?.held ?? []).map((h) => ({ ...h, number: issuedNumbers.get(h.invoice) ?? null })),
    settlements: (s.settlements ?? []).filter((r) => r.partner === p?.id), report_formats: p?.report_formats ?? [],
    remembered: s.transactions.remembered.filter((m) => !p || m.partner === p.id)
      .map((m) => ({ id: m.id, memory: m, text: keptText(m, s.partners.find((p) => p.id === m.partner)) })),
  };
  const start = Number(query.cursor || 0);
  const pages = Object.fromEntries((query.collection ? [query.collection] : PARTNER_COLLECTIONS).map((name) => {
    const rows = records[name];
    return [name, { data: rows.slice(start, start + 50).map((r) => boundedRecord(r)), total: rows.length, next_cursor: start + 50 < rows.length ? String(start + 50) : null }];
  })) as PartnerPages["pages"];
  const state = { ...fixtureShell(s),
    partners: p ? [{ ...p, held: [], report_formats: [] }] : [],
    record_counts: { ...s.record_counts, remembered: s.transactions.remembered.length } };
  return { state, pages };
}

