function boundedRecord(value: unknown, key = ""): unknown {
  if (Array.isArray(value)) {
    const aggregate = value.every((x) => x && typeof x === "object" && Object.keys(x).every((k) => k === "currency" || k === "total"));
    return (key === "companies" || key === "both" || aggregate ? value : value.slice(0, 50)).map((x) => boundedRecord(x));
  }
  return value && typeof value === "object" ? Object.fromEntries(Object.entries(value).map(([k, v]) => [k, boundedRecord(v, k)])) : value;
}

/** Full task-card construction is retained only as a fixture oracle. */
export function fixtureHomeTasks(ss: State[]): { all: string[]; brief: string[]; urgent: number } {
  const tag = ss.length > 1;
  const all: { key: string; urgent: boolean }[] = [];
  const seen = new Set<string>();
  for (const s of ss) {
    for (const { node, urgent } of taskCards(s, { tag })) {
      const k = String(node.key);
      if (seen.has(k)) continue;
      seen.add(k);
      all.push({ key: k, urgent });
    }
  }
  const urgent = all.filter((x) => x.urgent);
  return { all: all.map((x) => x.key), brief: (urgent.length ? urgent : all).slice(0, 3).map((x) => x.key), urgent: urgent.length };
}


/** Original full-state selectors, kept only for development and differential tests. */
export function fixtureDashboardData<C extends DashboardCollection>(view: View, collection: C, cursor = ""): Page<DashboardRows[C]> {
  const ss = "parts" in view ? view.parts : [view];
  const identity = (r: DashboardRows["upcoming"]) => JSON.stringify([r.company, r.kind, r.side, r.id]);
  const positions = new Map(ss.flatMap((s, firm) => s.dashboard.upcoming.map((r, ordinal) => [identity(r), `${firm}:${ordinal}`] as const)));
  const rows = collection === "upcoming" ? view.dashboard.upcoming.map((row, index) => {
    return { row, cursor: positions.get(identity(row)) ?? `0:${index}` };
  }) : ss.flatMap((s, firm) => {
    const held = s.partners.flatMap((p) => {
      const amounts = new Map<string, bigint>();
      for (const h of p.held ?? []) {
        const [whole, fraction] = h.amount.split(".");
        amounts.set(h.currency, (amounts.get(h.currency) ?? 0n) + BigInt(whole) * 100n + BigInt(fraction));
      }
      return [...amounts].map(([currency, amount]): HeldMoneyRow => ({ id: `${p.id}:${currency}`, company: s.co,
        partner: p.id, name: p.name, currency, amount: `${amount / 100n}.${String(amount % 100n).padStart(2, "0")}` }));
    });
    return held.map((row, ordinal) => ({ row, cursor: `${firm}:${ordinal}` }));
  });
  const start = cursor ? rows.findIndex((r) => r.cursor === cursor) + 1 : 0;
  const selected = rows.slice(start, start + 50);
  return { data: selected.map((r) => r.row) as DashboardRows[C][], total: rows.length,
    next_cursor: start + 50 < rows.length ? selected.at(-1)!.cursor : null };
}

/** Fake full-state replies build initial pages like the engine; compact replies already carry them. */
export function fixtureDashboardPages(view: View) {
  if ("bounded" in view && view.bounded) return;
  const pages = (v: View): DashboardPages => ({ upcoming: fixtureDashboardData(v, "upcoming"), held_money: fixtureDashboardData(v, "held_money") });
  for (const s of "parts" in view ? view.parts : []) s.dashboard_pages = pages(s);
  view.dashboard_pages = pages(view);
}

export async function fixtureDashboardPage<C extends DashboardCollection>(co: CoView, collection: C, cursor: string): Promise<Page<DashboardRows[C]>> {
  return fixtureDashboardData(await fixtureState(co), collection, cursor);
}

