/** Credits explained under `next dev` (transaction id → issued invoice id), until the page reloads, shown as the engine would. */
const linked = new Map<string, string>();
function linkedIn(s: State) {
  for (const t of s.transactions.rows) {
    const r = s.issued.find((x) => x.id === linked.get(t.id));
    if (!r || t.explanation) continue;
    const link: TxLink = { id: `fx-${t.id}`, tx: t.id, kind: "documents", other: null, partner: r.partner, payments: [], reason: null,
      parts: [{ id: r.id, amount: t.amount, closed: t.amount === r.left }], difference: fromCents(cents(t.amount) - cents(r.left)),
      currency: t.currency, note: "", rule: null, by: "admin", at: `${s.today}T10:15:00` };
    t.explanation = { kind: "collection", issued: [r.id], settlement: null, link };
    s.transactions.to_explain -= 1;
  }
}

/** Debits waiting for their invoice under `next dev` (transaction id → note), until the page reloads. */
const awaited = new Map<string, string>();
function awaitingIn(s: State) {
  for (const t of s.transactions.rows) {
    const note = awaited.get(t.id);
    if (note !== undefined && !t.explanation) t.awaiting = { note, by: "admin", at: `${s.today}T10:15:00` };
  }
}

