/** mail-detect and mail-test under `next dev`: gmail.com needs an app password, outlook.com signs in with Microsoft,
 * proton.me can't connect, a password "gresita" is refused; nothing connects anywhere. */
function fixtureMail(action: "mail-detect" | "mail-test", body: Record<string, unknown>) {
  const address = String(body.address ?? body.from_address), domain = address.split("@")[1] ?? "";
  const known: Record<string, [string, string, string]> = { "gmail.com": ["Gmail", "imap.gmail.com", "https://myaccount.google.com/apppasswords"],
    "outlook.com": ["Microsoft", "", ""], "proton.me": ["Proton Mail", "", ""] };
  const [provider, host, url] = known[domain] ?? ["IMAP", `imap.${domain}`, ""];
  if (action === "mail-test") return { code: body.password === "gresita" ? "wrong_password" : "ok", host: String(body.host ?? host), port: 993 };
  return { provider, host, port: 993, username: address, app_password_required: !!url, app_password_url: url, hint: "",
    supported: provider !== "Proton Mail", hosts: [host], method: provider === "Microsoft" ? "microsoft" : "imap" };
}

/** The Microsoft sign-in under `next dev`: an invented code, accepted on the third ask; an address starting with
 * "aprobare@" belongs to an organization that needs its administrator's approval. */
let microsoftAsks = 0;
function fixtureMicrosoft(action: "mail-microsoft-start" | "mail-microsoft-poll", body: Record<string, unknown>) {
  const id = String(body.id ?? "mail-fx-new");
  if (String(body.address).startsWith("aprobare@")) return { code: "admin_consent_required", id };
  if (action === "mail-microsoft-start") {
    microsoftAsks = 0;
    return { code: "authorization_pending", id, user_code: "KX7M2Q9TB", verification_uri: "https://microsoft.com/devicelogin", expires_in: 900, interval: 5 };
  }
  return { code: ++microsoftAsks < 3 ? "authorization_pending" : "connected", id, interval: 5 };
}

