/** An invented catalog: NORD sells a few things, STUDIO9 has none yet. */
function catalog(co: Co): Product[] {
  if (co !== "NORD") return [];
  const p = (id: string, kind: Product["kind"], name: string, code: string, unit: string, unit_price: string, rate: string, more: Partial<Product> = {}): Product =>
    ({ id, company: co, kind, name, code, unit, unit_price, currency: "RON", vat_category: "S", vat_rate: rate, exemption: "", description: "",
      archived: false, version: 1, can_delete: true, ...more });
  return [
    p("1", "serviciu", "Consultanță fiscală", "CONS-01", "HUR", "350.00", "21", { can_delete: false }),
    p("2", "produs", "Cutie de carton 40x30", "CUT-40", "H87", "12.50", "21"),
    p("3", "serviciu", "Abonament mentenanță", "", "DAY", "600.00", "21", { can_delete: false }),
    p("4", "produs", "Carte tipărită", "CRT-7", "H87", "45.00", "11"),
    p("5", "produs", "Cutie de carton 60x40", "CUT-60", "H87", "18.00", "21", { archived: true, can_delete: false }),
  ];
}

