export async function fixtureInvoicingPost(op: string, body: Record<string, unknown> & { co: Co }): Promise<InvoicingResult> {
  if (op === "client-lookup") return { ok: true, message: "", id: null, client: { name: "FIRMA EXEMPLU NOUĂ SRL", cui: String(body.cui),
    vat_id: `RO${body.cui}`, vat_payer: true, inactive: false, country: "RO",
    address: { street: "Str. Exemplului 3", city: "Iași", county: "RO-IS", postal_code: "700001", country: "RO" } } };
  return { ok: true, message: `Fixture: ${op} (nimic nu s-a schimbat).`, invoicing: await fixtureInvoicing(body.co), id: null };
}

// Answer like the engine would, without changing anything.
export async function fixturePost(action: Action, body: Record<string, unknown> & { co?: Co }): Promise<ActionResult> {
  if (action.startsWith("user-") || action === "session-close") return { ok: false, message: "Conturile se gestionează în instalarea fiscalm.", state: null };
  const state = (await fixtureSummary(body.co ?? "ALL")) as State;
  if (action === "bank-accounts") return { ok: true, message: body.operation === "confirm" ? "Conturile au fost conectate." : "", state,
    done: { id: "", held: "", ...{ offers: body.operation === "list" ? [{ id: "synthetic-offer", bank: "bt", valid_until: "2027-01-20",
      accounts: [{ id: "synthetic-choice-1", currency: "RON", last4: "0001", existing: true },
        { id: "synthetic-choice-2", currency: "EUR", last4: "0003", existing: false }] }] : [] } } };
  if (action === "bank-setup") return { ok: true, message: "Exemplu de configurare, fără conexiune la bancă.", state,
    done: { id: "", held: "", ...(body.operation === "prepare"
      ? { certificate: "-----BEGIN CERTIFICATE-----\nCERTIFICAT PUBLIC SINTETIC PENTRU PREVIZUALIZARE\n-----END CERTIFICATE-----", return_urls: ["https://fiscalm.example.com/bank/return"] }
      : { checks: [{ key: "return", ok: true, message: "Adresele de întoarcere sunt înregistrate." }] }) } };
  if (action === "tx-link" && body.tx && body.invoices && !body.kind) {
    linked.set(String(body.tx), String(body.invoices).split(",")[0]);
    return { ok: true, message: "Tranzacția a fost asociată cu factura.", state: (await fixtureSummary(body.co ?? "ALL")) as State,
      next: null, done: null, linked: { id: `fx-${body.tx}` } };
  }
  if (action === "tx-await") {
    if (body.on === "1") awaited.set(String(body.tx), String(body.note ?? "")); else awaited.delete(String(body.tx));
    return { ok: true, message: body.on === "1" ? "Tranzacția așteaptă factura." : "Tranzacția nu mai așteaptă factura.",
      state: (await fixtureSummary(body.co ?? "ALL")) as State, next: null, done: null };
  }
  if (action === "mail-detect" || action === "mail-test") return { ok: true, message: "", state: null, done: { id: "", held: "", ...fixtureMail(action, body) } };
  if (action === "mail-microsoft-start" || action === "mail-microsoft-poll") return { ok: true, message: "", state: null, done: { held: "", ...fixtureMicrosoft(action, body) } };
  const made: Record<string, AccessResult["done"]> = {
    "upload-link-create": { id: "l9", path: "/u/l9.exemplu", held: "" }, "token-create": { id: "t9", token: "fiscalm_exemplu", held: "" },
    "company-lookup": { id: "", cui: "33333330", legal_name: "FIRMA EXEMPLU NOUĂ SRL", address: "Str. Exemplului 3, Iași", vat_payer: true,
      inactive: false, held: "" } as AccessResult["done"],
  };
  if (action === "company-lookup" && String(body.cui).trim() === "00") // the fixtures' stand-in for ANAF not answering
    return { ok: false, message: "ANAF nu răspunde acum. Încearcă din nou peste câteva minute.", next: null, state: null,
      done: { id: "", held: "", retry: true } as AccessResult["done"] };
  if (action === "product-add") return { ok: true, message: "Produsul a fost salvat. (fixture)", state,
    done: { product: { ...(body as unknown as ProductFields), id: "9", company: String(body.co), archived: false, version: 1, can_delete: true } } } as ProductResult;
  if (made[action]) return { ok: true, message: "", state, done: made[action] };
  if (action === "mode-switch") return { ok: true, message: body.mode === "live" ? "Live este activ." : "Sandbox este activ.", state: null, next: null, done: null };
  const next = null;
  const said = action === "mark-paid" // the engine's words, so the toast reads as on a server
    ? "Factura a fost marcată ca plătită." : "";
  return { ok: true, message: said || `Fixture: ${action} (nimic nu s-a schimbat).`, state, next, done: null };
}
