/** A thermal paper photo: centred and left/right aligned lines in a monospace font, on a table. */
function paper(h: number, lines: [string, "m" | "l" | "r" | "lr", string?][]): string {
  const t = (x: number, y: number, s: string, a = "start", w = 400) =>
    `<text x='${x}' y='${y}' text-anchor='${a}' font-weight='${w}'>${s}</text>`;
  const body = lines.map(([s, a, r], i) => {
    const y = 70 + i * 26;
    if (a === "m") return t(180, y, s, "middle", 700);
    if (a === "lr") return t(40, y, s) + t(320, y, r ?? "", "end");
    return t(a === "l" ? 40 : 320, y, s, a === "l" ? "start" : "end");
  }).join("");
  return "data:image/svg+xml," + encodeURIComponent(
    `<svg xmlns='http://www.w3.org/2000/svg' width='360' height='${h}' viewBox='0 0 360 ${h}'><rect width='360' height='${h}' fill='#6b6259'/>`
    + `<path d='M18 14H342V${h - 22}${"l-12 8-12-8".repeat(13)}l-12 8V14Z' fill='#f4f1ea'/>`
    + `<g font-family='ui-monospace,Menlo,monospace' font-size='16' fill='#2b2925'>${body}</g></svg>`);
}

