/** A payment file's detail in development, as the engine answered it for the synthetic world (`npm run fixtures`). */
export async function fixturePaymentFile(id: number): Promise<PaymentFileDetail> {
  const files = (await import("../../fixtures/payment-files.json")).default as unknown as Record<string, PaymentFileDetail>;
  const f = files[String(id)];
  if (!f) throw new ApiError(404, "payment-files 404");
  return structuredClone(f);
}

